//! The pinned SnowLuma action catalog.
//!
//! `assets/catalog.json` is generated by `scripts/generate-catalog.mjs` from the
//! official docs MCP server and embedded at compile time. It
//! records the source version, fetch time, and a content hash so upgrades can be
//! diffed; runtime never contacts the docs server.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use serde::{Deserialize, Serialize};
use snafu::ResultExt;

use crate::error::{InitError, init};

/// The raw snapshot exactly as generated.
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Snapshot {
    pub source: SnapshotSource,
    pub fetched_at: String,
    pub hash: String,
    #[serde(default)]
    pub categories: Vec<Category>,
    pub actions: Vec<ActionDoc>,
    pub execution: serde_json::Value,
}

#[derive(Debug, Clone, Deserialize)]
pub struct SnapshotSource {
    pub package: String,
    pub version: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Category {
    pub category: String,
    pub count: usize,
}

/// One action's full documented contract.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ActionDoc {
    pub name: String,
    #[serde(default)]
    pub aliases: Vec<String>,
    #[serde(default)]
    pub summary: Option<String>,
    #[serde(default)]
    pub returns: Option<String>,
    #[serde(default)]
    pub returns_schema: Option<serde_json::Value>,
    #[serde(default)]
    pub read_only: bool,
    #[serde(default)]
    pub stream: bool,
    #[serde(default)]
    pub params: Vec<Param>,
    #[serde(default)]
    pub invariants: Vec<String>,
    #[serde(default)]
    pub input_schema: Option<serde_json::Value>,
    #[serde(default)]
    pub category: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Param {
    pub name: String,
    #[serde(default, rename = "type")]
    pub ty: Option<String>,
    #[serde(default)]
    pub required: bool,
    #[serde(default)]
    pub default: Option<serde_json::Value>,
    #[serde(default)]
    pub desc: Option<String>,
    #[serde(default)]
    pub values: Option<Vec<serde_json::Value>>,
    #[serde(default)]
    pub role: Option<String>,
    #[serde(default)]
    pub schema: Option<serde_json::Value>,
}

/// Parsed, indexed catalog ready for lookups.
#[derive(Debug)]
pub struct Catalog {
    pub version: String,
    pub hash: String,
    pub fetched_at: String,
    pub categories: Vec<Category>,
    pub actions: Vec<ActionDoc>,
    pub execution: serde_json::Value,
    /// canonical name and every alias → action index.
    by_name: BTreeMap<String, usize>,
}

const RAW: &str = include_str!("../assets/catalog.json");

static CATALOG: OnceLock<Catalog> = OnceLock::new();

impl Catalog {
    /// Parse the embedded snapshot. Called once at startup.
    pub fn load() -> Result<&'static Catalog, InitError> {
        if let Some(existing) = CATALOG.get() {
            return Ok(existing);
        }
        let snapshot: Snapshot = serde_json::from_str(RAW).context(init::CatalogJsonSnafu)?;
        let catalog = Catalog::from_snapshot(snapshot)?;
        let _ = CATALOG.set(catalog);
        // A racing caller may have set it first; both are equivalent.
        Ok(CATALOG.get().expect("catalog was set above"))
    }

    fn from_snapshot(snapshot: Snapshot) -> Result<Catalog, InitError> {
        if snapshot.actions.is_empty() {
            return init::CatalogShapeSnafu {
                reason: "no actions in snapshot".to_string(),
            }
            .fail();
        }
        let mut by_name = BTreeMap::new();
        for (index, action) in snapshot.actions.iter().enumerate() {
            if action.name.is_empty() {
                return init::CatalogShapeSnafu {
                    reason: format!("action at index {index} has an empty name"),
                }
                .fail();
            }
            for name in std::iter::once(&action.name).chain(action.aliases.iter()) {
                if let Some(previous) = by_name.insert(name.clone(), index) {
                    return init::CatalogShapeSnafu {
                        reason: format!(
                            "name `{name}` is claimed by both `{}` and `{}`",
                            snapshot.actions[previous].name, action.name
                        ),
                    }
                    .fail();
                }
            }
        }
        Ok(Catalog {
            version: snapshot.source.version,
            hash: snapshot.hash,
            fetched_at: snapshot.fetched_at,
            categories: snapshot.categories,
            actions: snapshot.actions,
            execution: snapshot.execution,
            by_name,
        })
    }

    /// Look up an action by canonical name or alias.
    pub fn get(&self, name: &str) -> Option<&ActionDoc> {
        self.by_name.get(name).map(|index| &self.actions[*index])
    }

    pub fn len(&self) -> usize {
        self.actions.len()
    }

    pub fn is_empty(&self) -> bool {
        self.actions.is_empty()
    }

    /// Fuzzy search over name, summary, aliases, and category.
    pub fn search(&self, query: &str) -> Vec<&ActionDoc> {
        let needle = query.trim().to_lowercase();
        if needle.is_empty() {
            return self.actions.iter().collect();
        }
        self.actions
            .iter()
            .filter(|action| {
                action.name.to_lowercase().contains(&needle)
                    || action
                        .summary
                        .as_deref()
                        .is_some_and(|summary| summary.to_lowercase().contains(&needle))
                    || action
                        .aliases
                        .iter()
                        .any(|alias| alias.to_lowercase().contains(&needle))
                    || action
                        .category
                        .as_deref()
                        .is_some_and(|category| category.to_lowercase().contains(&needle))
            })
            .collect()
    }

    pub fn in_category<'a>(&'a self, category: &str) -> Vec<&'a ActionDoc> {
        self.actions
            .iter()
            .filter(|action| action.category.as_deref() == Some(category))
            .collect()
    }
}
